# The shader loader's mutants. Dropped as equivalent, each with its reason:
#   * Removing both GmNameMap::Clear() calls from the database's destructor: the base destructor, which runs next, does the same clear.
#   * Not calling each staged component's Clear in AtShader::Clear: it logs nothing, the element's destructor resets the stage, and the array is freed at once, so only freed bytes differ. The function itself is compared when called directly.
#   * Removing the second GmNameMap::Clear() in the database's Clear or destructor: the first has emptied the map, so the second finds nothing to do.
#   * The order of the elements' destruction in DeleteArray: each element's destructor touches only that element, and nothing reads them after.
#   * AtStagedShaderComponent::Read's index, and AtShader::Read's database: neither is used, on either side.
S = "AtShader.cpp"
D = "AtShaderDatabase.cpp"

